import{_ as t,a,o as r,a6 as o}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Categories","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/catalog/categories/index.md","filePath":"api/graphql-api/admin/catalog/categories/index.md","lastUpdated":1786429091000}'),i={name:"api/graphql-api/admin/catalog/categories/index.md"};function d(s,e,n,c,l,g){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h1><p>Categories are the storefront&#39;s browsing tree — the sections customers navigate and products are assigned to. The Categories menu lists them (flat or as a nested tree), shows a single category, and creates / edits / deletes / moves them. It mirrors the admin <strong>Catalog → Categories</strong> screen.</p><h2 id="flat-list-vs-tree" tabindex="-1">Flat list vs. tree <a class="header-anchor" href="#flat-list-vs-tree" aria-label="Permalink to &quot;Flat list vs. tree&quot;">​</a></h2><p>Two read shapes for the same data:</p><ul><li><strong>List</strong> (<code>adminCategories</code>) — a flat, cursor-paginated, filterable datagrid of categories. Each row carries the category&#39;s own fields plus its <code>parentId</code>.</li><li><strong>Tree</strong> (<code>adminCategoryTrees</code>) — the full nested hierarchy, each node carrying its <code>children</code> recursively. Use this to render the category tree in one call.</li></ul><h2 id="hierarchy-status-display" tabindex="-1">Hierarchy, status, display <a class="header-anchor" href="#hierarchy-status-display" aria-label="Permalink to &quot;Hierarchy, status, display&quot;">​</a></h2><ul><li><strong><code>parentId</code></strong> places a category under its parent. The root category (<code>id = 1</code>) and any channel&#39;s root category are structural and <strong>cannot be deleted</strong>.</li><li><strong>Moving</strong> a category is just an update with a new <code>parentId</code> (and <code>position</code>) — there is no separate &quot;move&quot; operation.</li><li><strong><code>status</code></strong> (1 enabled / 0 disabled) and <strong><code>position</code></strong> (sort order among siblings).</li><li><strong><code>displayMode</code></strong> — what the category page shows: <code>products_and_description</code>, <code>products_only</code>, or <code>description_only</code>.</li></ul><h2 id="nested-data-is-returned-whole" tabindex="-1">Nested data is returned whole <a class="header-anchor" href="#nested-data-is-returned-whole" aria-label="Permalink to &quot;Nested data is returned whole&quot;">​</a></h2><p>On the single-category query, <code>translations</code> and <code>filterableAttributeIds</code> are returned as <strong>whole JSON</strong> — query each as a bare field (<code>translations</code>, not <code>translations { … }</code>); the entire array comes back, and it resolves over GraphQL. The tree&#39;s <code>children</code> are likewise whole JSON nodes. The listing leaves <code>translations</code> / <code>filterableAttributeIds</code> out (detail-only).</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/catalog/categories/categories-listing.html">List categories</a></td><td><code>adminCategories</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/categories/categories-tree.html">Category tree</a></td><td><code>adminCategoryTrees</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/categories/categories-detail.html">Category detail</a></td><td><code>adminCategory(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/categories/categories-create.html">Create category</a></td><td><code>createAdminCategory</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/categories/categories-update.html">Update / move category</a></td><td><code>updateAdminCategory</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/categories/categories-delete.html">Delete category</a></td><td><code>deleteAdminCategory</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/categories/categories-mass-delete.html">Mass delete</a></td><td><code>createAdminCategoryMassDelete</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/categories/categories-mass-update-status.html">Mass update status</a></td><td><code>createAdminCategoryMassUpdateStatus</code> mutation</td></tr></tbody></table><p>All Categories operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>. Reads require <code>catalog.categories.view</code>; writes require the matching <code>catalog.categories.create</code> / <code>.edit</code> / <code>.delete</code> permission.</p>',12)]))}const u=t(i,[["render",d]]);export{p as __pageData,u as default};
